import{_ as s,o as t,c as n,aN as r}from"./chunks/framework.D31DlcCL.js";const o="/img/math-shape-counting.svg",d=JSON.parse('{"title":"奥数基础：图形数一数，不重复、不遗漏的秘诀","description":"数图形是小学奥数中最常见的题型之一。如何在一堆乱糟糟的线条中数出所有的三角形或长方形？本文教你一套系统的“编号分类法”，让你数得又快又准。","frontmatter":{"title":"奥数基础：图形数一数，不重复、不遗漏的秘诀","date":"2026-02-11T11:00:00.000Z","categories":["数学"],"tags":["小学奥数","图形计数","分类讨论","空间思维"],"description":"数图形是小学奥数中最常见的题型之一。如何在一堆乱糟糟的线条中数出所有的三角形或长方形？本文教你一套系统的“编号分类法”，让你数得又快又准。","cover":"/img/math-shape-counting.svg","top_img":"/img/banner.svg","toc_number":true},"headers":[],"relativePath":"posts/primary-math-olympiad-counting-shapes.md","filePath":"posts/primary-math-olympiad-counting-shapes.md","lastUpdated":null}'),l={name:"posts/primary-math-olympiad-counting-shapes.md"};function e(i,a,m,p,h,c){return t(),n("div",null,[...a[0]||(a[0]=[r('<h1 id="奥数基础-图形数一数-不重复、不遗漏的秘诀" tabindex="-1">奥数基础：图形数一数，不重复、不遗漏的秘诀 <a class="header-anchor" href="#奥数基础-图形数一数-不重复、不遗漏的秘诀" aria-label="Permalink to &quot;奥数基础：图形数一数，不重复、不遗漏的秘诀&quot;">​</a></h1><p>“图中有多少个三角形？” 面对这种题目，很多小朋友数着数着就乱了，一会儿多出一个，一会儿漏掉一个。</p><p>其实，数图形不是靠眼力“硬数”，而是要靠<strong>分类和系统的方法</strong>。今天我们就来学习数图形的最高准则：<strong>不重复、不遗漏</strong>。</p><hr><h2 id="一、-核心法宝-编号分类法" tabindex="-1">一、 核心法宝：编号分类法 <a class="header-anchor" href="#一、-核心法宝-编号分类法" aria-label="Permalink to &quot;一、 核心法宝：编号分类法&quot;">​</a></h2><p>数图形最怕“胡子眉毛一把抓”。正确的做法是给每一个最基础的小图形<strong>编上号</strong>。</p><p><img src="'+o+'" alt="图形计数示意图"></p><p><strong>【数数三部曲】</strong>：</p><ol><li><strong>看单体</strong>：数一数由 1 个小块组成的图形有几个。</li><li><strong>看组合</strong>：数一数由 2 个、3 个……小块拼成的大图形有几个。</li><li><strong>求总和</strong>：把所有类别的数量加在一起。</li></ol><hr><h2 id="二、-实战模型解析" tabindex="-1">二、 实战模型解析 <a class="header-anchor" href="#二、-实战模型解析" aria-label="Permalink to &quot;二、 实战模型解析&quot;">​</a></h2><h3 id="模型-1-线段上的点" tabindex="-1">模型 1：线段上的点 <a class="header-anchor" href="#模型-1-线段上的点" aria-label="Permalink to &quot;模型 1：线段上的点&quot;">​</a></h3><p><strong>题目</strong>：一条线段上有 4 个点（包括两端），一共有多少条线段？ <strong>解析</strong>：</p><ul><li>给点编号：A, B, C, D。</li><li>1 份线段（短）：AB, BC, CD（3条）</li><li>2 份线段（中）：AC, BD（2条）</li><li>3 份线段（长）：AD（1条） <strong>总计</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mo>+</mo><mn>2</mn><mo>+</mo><mn>1</mn><mo>=</mo><mn>6</mn></mrow><annotation encoding="application/x-tex">3 + 2 + 1 = 6</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mbin">+</span><span class="mord mathrm">2</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">6</span></span></span></span>（条）。</li></ul><h3 id="模型-2-数三角形" tabindex="-1">模型 2：数三角形 <a class="header-anchor" href="#模型-2-数三角形" aria-label="Permalink to &quot;模型 2：数三角形&quot;">​</a></h3><p><strong>题目</strong>：如封面图所示，一个大三角形中间画了一条垂直线。 <strong>解析</strong>：</p><ol><li><strong>基础小三角形</strong>：编号 1 和 2，共 2 个。</li><li><strong>组合三角形</strong>：1 和 2 拼在一起的大三角形，共 1 个。 <strong>总计</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mo>+</mo><mn>1</mn><mo>=</mo><mn>3</mn></mrow><annotation encoding="application/x-tex">2 + 1 = 3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">3</span></span></span></span>（个）。</li></ol><hr><h2 id="三、-进阶技巧-打标记与层级法" tabindex="-1">三、 进阶技巧：打标记与层级法 <a class="header-anchor" href="#三、-进阶技巧-打标记与层级法" aria-label="Permalink to &quot;三、 进阶技巧：打标记与层级法&quot;">​</a></h2><p>当图形非常复杂（比如有很多层）时，我们可以按层来数。</p><ul><li>第一层有几个？</li><li>第二层有几个？</li><li>跨层组合的有几个？</li></ul><p><strong>【重要提醒】</strong>：一定要按照从小到大，或者从左到右的顺序，千万不要东数一个西数一个！</p><hr><h2 id="四、-避坑指南-看清形状" tabindex="-1">四、 避坑指南：看清形状 <a class="header-anchor" href="#四、-避坑指南-看清形状" aria-label="Permalink to &quot;四、 避坑指南：看清形状&quot;">​</a></h2><p>有些题目会问“有多少个正方形”，这时候千万别把长方形也数进去！</p><ul><li><strong>正方形</strong>：四条边都相等。</li><li><strong>长方形</strong>：对边相等即可。 数之前，先确定你要找的“目标人物”长什么样。</li></ul><hr><h2 id="五、-练一练-图形小侦探" tabindex="-1">五、 练一练（图形小侦探） <a class="header-anchor" href="#五、-练一练-图形小侦探" aria-label="Permalink to &quot;五、 练一练（图形小侦探）&quot;">​</a></h2><ol><li><strong>数线段</strong>：一条路上有 5 棵树，每两棵树之间是一段路，请问一共有多少段路？</li><li><strong>数角</strong>：从一个点出发引出 4 条射线，一共组成了多少个角？</li><li><strong>数长方形</strong>：一个“田”字格里，一共有多少个长方形（包括正方形）？</li></ol><hr><p><em>总结：数图形是一场耐心的游戏。只要你学会了编号和分类，再复杂的迷宫也难不倒你！</em></p>',31)])])}const u=s(l,[["render",e]]);export{d as __pageData,u as default};
